-- Repeatable star-schema load pattern used by python -m warehouse.snowflake.run_star --execute.
-- LIMITATION: this file is not a standalone COPY FROM Parquet script and must not SELECT star
-- rows from snapshot tables. Dimensions and facts are prepared locally (deterministic keys,
-- contact columns omitted, invalid parents skipped). customers.parquet and reviews.parquet are
-- excluded from the snapshot loader, so DIM_CUSTOMER and FACT_REVIEWS cannot be rebuilt from
-- FOODPULSE.ANALYTICS mining snapshots. A stage/COPY process would conflict with the publisher.
-- The Python loader binds prepared rows into a temporary staging table, checks COUNT(*), then
-- INSERT OVERWRITE into the published table. Reruns replace rows; they do not append.
-- Do not run this file against a live account from CI. Do not run it as a local dry-run.

CREATE OR REPLACE TEMPORARY TABLE FOODPULSE.ANALYTICS.DIM_DATE_LOAD_STAGING AS SELECT * FROM FOODPULSE.ANALYTICS.DIM_DATE WHERE 1 = 0;
-- INSERT INTO FOODPULSE.ANALYTICS.DIM_DATE_LOAD_STAGING (DATE_SK, DATE_DAY, YEAR, QUARTER, MONTH, MONTH_NAME, DAY, DAY_OF_WEEK, DAY_NAME, IS_WEEKEND, LOADED_AT) VALUES (...) uses bound parameters from the local transform.
INSERT OVERWRITE INTO FOODPULSE.ANALYTICS.DIM_DATE SELECT * FROM FOODPULSE.ANALYTICS.DIM_DATE_LOAD_STAGING;

CREATE OR REPLACE TEMPORARY TABLE FOODPULSE.ANALYTICS.DIM_CUSTOMER_LOAD_STAGING AS SELECT * FROM FOODPULSE.ANALYTICS.DIM_CUSTOMER WHERE 1 = 0;
-- INSERT INTO FOODPULSE.ANALYTICS.DIM_CUSTOMER_LOAD_STAGING (CUSTOMER_SK, CUSTOMER_ID, CITY, GENDER, CREATED_AT, LOADED_AT) VALUES (...) uses bound parameters from the local transform.
INSERT OVERWRITE INTO FOODPULSE.ANALYTICS.DIM_CUSTOMER SELECT * FROM FOODPULSE.ANALYTICS.DIM_CUSTOMER_LOAD_STAGING;

CREATE OR REPLACE TEMPORARY TABLE FOODPULSE.ANALYTICS.DIM_RESTAURANT_LOAD_STAGING AS SELECT * FROM FOODPULSE.ANALYTICS.DIM_RESTAURANT WHERE 1 = 0;
-- INSERT INTO FOODPULSE.ANALYTICS.DIM_RESTAURANT_LOAD_STAGING (RESTAURANT_SK, RESTAURANT_ID, NAME, CUISINE_TYPE, IS_ACTIVE, CITY, STATE, COUNTRY, CREATED_AT, LOADED_AT) VALUES (...) uses bound parameters from the local transform.
INSERT OVERWRITE INTO FOODPULSE.ANALYTICS.DIM_RESTAURANT SELECT * FROM FOODPULSE.ANALYTICS.DIM_RESTAURANT_LOAD_STAGING;

CREATE OR REPLACE TEMPORARY TABLE FOODPULSE.ANALYTICS.DIM_FOOD_ITEM_LOAD_STAGING AS SELECT * FROM FOODPULSE.ANALYTICS.DIM_FOOD_ITEM WHERE 1 = 0;
-- INSERT INTO FOODPULSE.ANALYTICS.DIM_FOOD_ITEM_LOAD_STAGING (FOOD_ITEM_SK, FOOD_ITEM_ID, RESTAURANT_SK, RESTAURANT_ID, NAME, CATEGORY, PRICE, IS_AVAILABLE, CREATED_AT, LOADED_AT) VALUES (...) uses bound parameters from the local transform.
INSERT OVERWRITE INTO FOODPULSE.ANALYTICS.DIM_FOOD_ITEM SELECT * FROM FOODPULSE.ANALYTICS.DIM_FOOD_ITEM_LOAD_STAGING;

CREATE OR REPLACE TEMPORARY TABLE FOODPULSE.ANALYTICS.FACT_ORDERS_LOAD_STAGING AS SELECT * FROM FOODPULSE.ANALYTICS.FACT_ORDERS WHERE 1 = 0;
-- INSERT INTO FOODPULSE.ANALYTICS.FACT_ORDERS_LOAD_STAGING (ORDER_SK, ORDER_ID, DATE_SK, CUSTOMER_SK, RESTAURANT_SK, STATUS, TOTAL_AMOUNT, DISCOUNT_USED, TOTAL_AMOUNT_CAPPED, IS_TOTAL_OUTLIER, ORDER_TS, LOADED_AT) VALUES (...) uses bound parameters from the local transform.
INSERT OVERWRITE INTO FOODPULSE.ANALYTICS.FACT_ORDERS SELECT * FROM FOODPULSE.ANALYTICS.FACT_ORDERS_LOAD_STAGING;

CREATE OR REPLACE TEMPORARY TABLE FOODPULSE.ANALYTICS.FACT_REVIEWS_LOAD_STAGING AS SELECT * FROM FOODPULSE.ANALYTICS.FACT_REVIEWS WHERE 1 = 0;
-- INSERT INTO FOODPULSE.ANALYTICS.FACT_REVIEWS_LOAD_STAGING (REVIEW_SK, REVIEW_ID, DATE_SK, CUSTOMER_SK, RESTAURANT_SK, ORDER_SK, RATING, REVIEW_TS, LOADED_AT) VALUES (...) uses bound parameters from the local transform.
INSERT OVERWRITE INTO FOODPULSE.ANALYTICS.FACT_REVIEWS SELECT * FROM FOODPULSE.ANALYTICS.FACT_REVIEWS_LOAD_STAGING;
